content:
:root {
  --bg-primary: #0f141c;
  --bg-secondary: #18202c;
  --bg-card: rgba(26, 35, 49, 0.85);
  --bg-card-hover: rgba(33, 44, 62, 0.95);
  --border-color: rgba(255, 255, 255, 0.1);
  --border-focus: #3b82f6;
  --text-main: #f1f5f9;
  --text-muted: #94a3b8;
  --text-dim: #64748b;
  --accent: #3b82f6;
  --accent-hover: #2563eb;
  --accent-glow: rgba(59, 130, 246, 0.35);
  --shadow-sm: 0 2px 4px rgba(0, 0, 0, 0.2);
  --shadow-md: 0 4px 16px rgba(0, 0, 0, 0.3);
  --shadow-lg: 0 8px 32px rgba(0, 0, 0, 0.45);
  --radius-sm: 6px;
  --radius-md: 10px;
  --radius-lg: 16px;
  --font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, "Helvetica Neue", Arial, sans-serif;
}

* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
}

body {
  font-family: var(--font-family);
  background-color: var(--bg-primary);
  color: var(--text-main);
  min-height: 100vh;
  overflow-x: hidden;
  user-select: none;
}

/* アプリケーションコンテナ */
.app-container {
  display: flex;
  flex-direction: column;
  min-height: 100vh;
  max-width: 1440px;
  margin: 0 auto;
  padding: 16px 24px;
}

/* ヘッダー */
.header {
  text-align: center;
  margin-bottom: 20px;
  padding: 8px 0;
}

.title {
  font-size: 1.85rem;
  font-weight: 700;
  letter-spacing: -0.02em;
  background: linear-gradient(135deg, #ffffff 0%, #93c5fd 60%, #3b82f6 100%);
  -webkit-background-clip: text;
  -webkit-text-fill-color: transparent;
  margin-bottom: 6px;
}

.subtitle {
  font-size: 0.95rem;
  color: var(--text-muted);
  font-weight: 400;
}

/* メインレイアウト */
.main-layout {
  display: flex;
  flex: 1;
  gap: 24px;
  align-items: stretch;
  min-height: 520px;
}

/* 3Dキャンバス領域 */
.canvas-wrapper {
  flex: 1 1 65%;
  position: relative;
  background: radial-gradient(circle at center, #1e293b 0%, #0a0f18 100%);
  border-radius: var(--radius-lg);
  border: 1px solid var(--border-color);
  box-shadow: var(--shadow-md);
  overflow: hidden;
  display: flex;
  flex-direction: column;
}

.canvas-container {
  width: 100%;
  height: 100%;
  flex: 1;
  position: relative;
  cursor: grab;
  touch-action: none;
}

.canvas-container:active {
  cursor: grabbing;
}

.canvas-container canvas {
  display: block;
  width: 100% !important;
  height: 100% !important;
}

.canvas-hint {
  position: absolute;
  bottom: 16px;
  left: 50%;
  transform: translateX(-50%);
  background-color: rgba(15, 23, 42, 0.75);
  backdrop-filter: blur(8px);
  -webkit-backdrop-filter: blur(8px);
  color: var(--text-muted);
  font-size: 0.8rem;
  padding: 6px 14px;
  border-radius: 20px;
  border: 1px solid rgba(255, 255, 255, 0.08);
  pointer-events: none;
  white-space: nowrap;
  letter-spacing: 0.02em;
  z-index: 5;
}

/* コントロールパネル */
.panel-container {
  flex: 0 0 340px;
  background-color: var(--bg-card);
  backdrop-filter: blur(12px);
  -webkit-backdrop-filter: blur(12px);
  border-radius: var(--radius-lg);
  border: 1px solid var(--border-color);
  padding: 24px;
  display: flex;
  flex-direction: column;
  gap: 20px;
  box-shadow: var(--shadow-md);
  overflow-y: auto;
  max-height: calc(100vh - 160px);
}

.panel-title {
  font-size: 1.15rem;
  font-weight: 600;
  color: var(--text-main);
  padding-bottom: 10px;
  border-bottom: 1px solid var(--border-color);
  display: flex;
  align-items: center;
  justify-content: space-between;
}

.control-group {
  display: flex;
  flex-direction: column;
  gap: 10px;
}

.label {
  font-size: 0.85rem;
  font-weight: 600;
  color: var(--text-muted);
  text-transform: uppercase;
  letter-spacing: 0.05em;
}

/* カラーピッカー＆スウォッチ */
.color-picker-group {
  display: flex;
  align-items: center;
  gap: 12px;
}

.color-swatches {
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
}

.color-swatch {
  width: 32px;
  height: 32px;
  border-radius: 50%;
  border: 2px solid transparent;
  cursor: pointer;
  transition: transform 0.15s ease, border-color 0.15s ease, box-shadow 0.15s ease;
  box-shadow: 0 2px 5px rgba(0, 0, 0, 0.3);
}

.color-swatch:hover {
  transform: scale(1.12);
}

.color-swatch.active {
  border-color: #ffffff;
  transform: scale(1.15);
  box-shadow: 0 0 10px var(--accent-glow);
}

/* スライダー */
.slider-group {
  display: flex;
  flex-direction: column;
  gap: 6px;
}

.slider-label {
  display: flex;
  justify-content: space-between;
  align-items: center;
  font-size: 0.85rem;
  color: var(--text-muted);
}

.slider-label span:last-child {
  font-weight: 600;
  color: var(--accent);
  font-variant-numeric: tabular-nums;
}

.slider-input {
  -webkit-appearance: none;
  appearance: none;
  width: 100%;
  height: 6px;
  border-radius: 3px;
  background: #334155;
  outline: none;
  cursor: pointer;
  transition: background 0.2s;
}

.slider-input::-webkit-slider-thumb {
  -webkit-appearance: none;
  appearance: none;
  width: 18px;
  height: 18px;
  border-radius: 50%;
  background: var(--accent);
  cursor: pointer;
  box-shadow: 0 0 6px rgba(59, 130, 246, 0.6);
  transition: transform 0.1s ease, background-color 0.15s ease;
}

.slider-input::-webkit-slider-thumb:hover {
  transform: scale(1.2);
  background: #60a5fa;
}

.slider-input::-moz-range-thumb {
  width: 18px;
  height: 18px;
  border-radius: 50%;
  background: var(--accent);
  cursor: pointer;
  border: none;
  box-shadow: 0 0 6px rgba(59, 130, 246, 0.6);
  transition: transform 0.1s ease, background-color 0.15s ease;
}

.slider-input::-moz-range-thumb:hover {
  transform: scale(1.2);
  background: #60a5fa;
}

/* トグル・チェックボックス */
.toggle-group {
  display: flex;
  flex-direction: column;
  gap: 12px;
}

.toggle-label {
  display: flex;
  align-items: center;
  justify-content: space-between;
  font-size: 0.9rem;
  color: var(--text-main);
  cursor: pointer;
  user-select: none;
}

.checkbox-input {
  appearance: none;
  -webkit-appearance: none;
  width: 44px;
  height: 24px;
  background-color: #334155;
  border-radius: 12px;
  position: relative;
  outline: none;
  cursor: pointer;
  transition: background-color 0.25s ease;
}

.checkbox-input::after {
  content: "";
  position: absolute;
  top: 3px;
  left: 3px;
  width: 18px;
  height: 18px;
  border-radius: 50%;
  background-color: #ffffff;
  transition: transform 0.25s ease;
}

.checkbox-input:checked {
  background-color: var(--accent);
}

.checkbox-input:checked::after {
  transform: translateX(20px);
}

/* ボタングループ */
.button-group {
  display: flex;
  gap: 10px;
  margin-top: auto;
  padding-top: 10px;
}

.btn {
  flex: 1;
  padding: 12px 16px;
  border: none;
  border-radius: var(--radius-md);
  font-size: 0.9rem;
  font-weight: 600;
  cursor: pointer;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 8px;
  transition: all 0.2s ease;
  min-height: 44px;
}

.btn-reset {
  background-color: rgba(239, 68, 68, 0.15);
  color: #f87171;
  border: 1px solid rgba(239, 68, 68, 0.3);
}

.btn-reset:hover {
  background-color: rgba(239, 68, 68, 0.25);
  border-color: rgba(239, 68, 68, 0.5);
  transform: translateY(-1px);
}

.btn-reset:active {
  transform: translateY(0);
}

/* ステータスバー */
.status-bar {
  display: flex;
  align-items: center;
  justify-content: space-between;
  margin-top: 16px;
  padding: 10px 18px;
  background-color: var(--bg-card);
  border-radius: var(--radius-md);
  border: 1px solid var(--border-color);
  font-size: 0.8rem;
  color: var(--text-dim);
}

.status-item {
  display: flex;
  align-items: center;
  gap: 6px;
}

.status-item strong {
  color: var(--text-muted);
}

/* レスポンシブ対応 */
@media (max-width: 900px) {
  .main-layout {
    flex-direction: column;
  }

  .canvas-wrapper {
    min-height: 380px;
    height: 48vh;
  }

  .panel-container {
    flex: auto;
    max-height: none;
    overflow-y: visible;
  }

  .app-container {
    padding: 12px 14px;
  }

  .status-bar {
    flex-direction: column;
    gap: 8px;
    align-items: flex-start;
  }
}

@media (max-width: 480px) {
  .title {
    font-size: 1.5rem;
  }

  .canvas-hint {
    font-size: 0.72rem;
    padding: 4px 10px;
  }

  .color-swatch {
    width: 28px;
    height: 28px;
  }

  .panel-container {
    padding: 16px;
  }
}

export interface CubeConfig {
  color: string;
  wireframe: boolean;
  autoRotate: boolean;
  rotationSpeed: number;
  roughness: number;
  metalness: number;
}

export interface ControlPanelProps {
  config: CubeConfig;
  onChangeConfig: (newConfig: Partial<CubeConfig>) => void;
  onReset: () => void;
}

export interface CubeCanvasProps {
  config: CubeConfig;
}

import { useEffect, useRef } from 'react';
import * as THREE from 'three';
import { CubeCanvasProps } from '../types';

export default function CubeCanvas({ config }: CubeCanvasProps) {
  const containerRef = useRef<HTMLDivElement>(null);
  const sceneRef = useRef<THREE.Scene | null>(null);
  const cameraRef = useRef<THREE.PerspectiveCamera | null>(null);
  const rendererRef = useRef<THREE.WebGLRenderer | null>(null);
  const meshRef = useRef<THREE.Mesh<THREE.BoxGeometry, THREE.MeshStandardMaterial> | null>(null);
  const edgesRef = useRef<THREE.LineSegments | null>(null);

  // マウス・タッチによる回転・ズーム操作用
  const isDraggingRef = useRef(false);
  const prevPointerRef = useRef({ x: 0, y: 0 });
  const sphericalRef = useRef({ radius: 4.5, theta: Math.PI / 4, phi: Math.PI / 3 });
  const touchDistanceRef = useRef<number | null>(null);
  const configRef = useRef(config);

  useEffect(() => {
    configRef.current = config;
  }, [config]);

  // Three.js シーン初期化
  useEffect(() => {
    const container = containerRef.current;
    if (!container) return;

    const width = container.clientWidth || 600;
    const height = container.clientHeight || 450;

    // シーン
    const scene = new THREE.Scene();
    sceneRef.current = scene;

    // カメラ
    const camera = new THREE.PerspectiveCamera(45, width / height, 0.1, 100);
    cameraRef.current = camera;

    const updateCameraPosition = () => {
      const { radius, theta, phi } = sphericalRef.current;
      camera.position.x = radius * Math.sin(phi) * Math.sin(theta);
      camera.position.y = radius * Math.cos(phi);
      camera.position.z = radius * Math.sin(phi) * Math.cos(theta);
      camera.lookAt(0, 0, 0);
    };
    updateCameraPosition();

    // レンダラー
    const renderer = new THREE.WebGLRenderer({ antialias: true, alpha: true });
    renderer.setSize(width, height);
    renderer.setPixelRatio(Math.min(window.devicePixelRatio, 2));
    renderer.shadowMap.enabled = true;
    renderer.shadowMap.type = THREE.PCFSoftShadowMap;
    rendererRef.current = renderer;

    container.appendChild(renderer.domElement);

    // ライティング
    const ambientLight = new THREE.AmbientLight(0xffffff, 0.7);
    scene.add(ambientLight);

    const dirLight1 = new THREE.DirectionalLight(0xffffff, 1.2);
    dirLight1.position.set(5, 8, 5);
    scene.add(dirLight1);

    const dirLight2 = new THREE.DirectionalLight(0x60a5fa, 0.6);
    dirLight2.position.set(-5, -3, -5);
    scene.add(dirLight2);

    // ジオメトリ＆マテリアル
    const geometry = new THREE.BoxGeometry(2, 2, 2);
    const material = new THREE.MeshStandardMaterial({
      color: config.color,
      roughness: config.roughness,
      metalness: config.metalness,
      wireframe: config.wireframe,
    });
    const mesh = new THREE.Mesh(geometry, material);
    meshRef.current = mesh;
    scene.add(mesh);

    // エッジライン（立方体の稜線を綺麗に見せる補助枠）
    const edgesGeometry = new THREE.EdgesGeometry(geometry);
    const edgesMaterial = new THREE.LineBasicMaterial({
      color: 0xffffff,
      transparent: true,
      opacity: 0.35,
    });
    const edges = new THREE.LineSegments(edgesGeometry, edgesMaterial);
    edgesRef.current = edges;
    mesh.add(edges);

    // グリッド床
    const gridHelper = new THREE.GridHelper(10, 20, 0x3b82f6, 0x1e293b);
    gridHelper.position.y = -1.5;
    scene.add(gridHelper);

    // アニメーションループ
    let animationFrameId: number;
    let lastTime = performance.now();

    const animate = (currentTime: number) => {
      animationFrameId = requestAnimationFrame(animate);
      const delta = (currentTime - lastTime) / 1000;
      lastTime = currentTime;

      const currentConfig = configRef.current;

      // 自動回転
      if (currentConfig.autoRotate && !isDraggingRef.current) {
        sphericalRef.current.theta += currentConfig.rotationSpeed * delta;
        updateCameraPosition();
      }

      renderer.render(scene, camera);
    };

    animationFrameId = requestAnimationFrame(animate);

    // リサイズハンドラ
    const handleResize = () => {
      if (!container || !renderer || !camera) return;
      const newWidth = container.clientWidth;
      const newHeight = container.clientHeight;
      camera.aspect = newWidth / newHeight;
      camera.updateProjectionMatrix();
      renderer.setSize(newWidth, newHeight);
    };

    window.addEventListener('resize', handleResize);

    // クリーンアップ
    return () => {
      window.removeEventListener('resize', handleResize);
      cancelAnimationFrame(animationFrameId);
      if (container.contains(renderer.domElement)) {
        container.removeChild(renderer.domElement);
      }
      geometry.dispose();
      material.dispose();
      edgesGeometry.dispose();
      edgesMaterial.dispose();
      renderer.dispose();
    };
  }, []);

  // 設定変更時のマテリアル・表示更新
  useEffect(() => {
    if (!meshRef.current) return;
    const material = meshRef.current.material;
    material.color.set(config.color);
    material.roughness = config.roughness;
    material.metalness = config.metalness;
    material.wireframe = config.wireframe;
    material.needsUpdate = true;

    if (edgesRef.current) {
      edgesRef.current.visible = !config.wireframe;
    }
  }, [config.color, config.roughness, config.metalness, config.wireframe]);

  // マウス＆タッチ操作ハンドラ
  const updateCamera = () => {
    if (!cameraRef.current) return;
    const { radius, theta, phi } = sphericalRef.current;
    cameraRef.current.position.x = radius * Math.sin(phi) * Math.sin(theta);
    cameraRef.current.position.y = radius * Math.cos(phi);
    cameraRef.current.position.z = radius * Math.sin(phi) * Math.cos(theta);
    cameraRef.current.lookAt(0, 0, 0);
  };

  const handlePointerDown = (e: React.PointerEvent) => {
    isDraggingRef.current = true;
    prevPointerRef.current = { x: e.clientX, y: e.clientY };
    (e.target as HTMLElement).setPointerCapture?.(e.pointerId);
  };

  const handlePointerMove = (e: React.PointerEvent) => {
    if (!isDraggingRef.current) return;
    const deltaX = e.clientX - prevPointerRef.current.x;
    const deltaY = e.clientY - prevPointerRef.current.y;

    sphericalRef.current.theta -= deltaX * 0.008;
    sphericalRef.current.phi -= deltaY * 0.008;

    // 上下の角度制限（反転防止）
    const minPhi = 0.05;
    const maxPhi = Math.PI - 0.05;
    sphericalRef.current.phi = Math.max(minPhi, Math.min(maxPhi, sphericalRef.current.phi));

    prevPointerRef.current = { x: e.clientX, y: e.clientY };
    updateCamera();
  };

  const handlePointerUp = (e: React.PointerEvent) => {
    isDraggingRef.current = false;
    try {
      (e.target as HTMLElement).releasePointerCapture?.(e.pointerId);
    } catch {
      // releasePointerCapture failure can happen gracefully
    }
  };

  const handleWheel = (e: React.WheelEvent) => {
    e.preventDefault();
    sphericalRef.current.radius += e.deltaY * 0.005;
    sphericalRef.current.radius = Math.max(2.5, Math.min(10.0, sphericalRef.current.radius));
    updateCamera();
  };

  // 2本指ピンチズーム対応
  const handleTouchMove = (e: React.TouchEvent) => {
    if (e.touches.length === 2) {
      const t1 = e.touches[0];
      const t2 = e.touches[1];
      const dist = Math.hypot(t1.clientX - t2.clientX, t1.clientY - t2.clientY);

      if (touchDistanceRef.current !== null) {
        const delta = touchDistanceRef.current - dist;
        sphericalRef.current.radius += delta * 0.01;
        sphericalRef.current.radius = Math.max(2.5, Math.min(10.0, sphericalRef.current.radius));
        updateCamera();
      }
      touchDistanceRef.current = dist;
    }
  };

  const handleTouchEnd = () => {
    touchDistanceRef.current = null;
  };

  return (
    <div
      className="canvas-container"
      ref={containerRef}
      onPointerDown={handlePointerDown}
      onPointerMove={handlePointerMove}
      onPointerUp={handlePointerUp}
      onPointerCancel={handlePointerUp}
      onWheel={handleWheel}
      onTouchMove={handleTouchMove}
      onTouchEnd={handleTouchEnd}
    >
      <div className="canvas-hint">
        ドラッグ/スワイプで360°回転 • スクロール/ピンチで拡大縮小
      </div>
    </div>
  );
}

import { ControlPanelProps } from '../types';

const PRESET_COLORS = [
  '#3b82f6', // ブルー
  '#10b981', // エメラルド
  '#f59e0b', // アンバー
  '#ef4444', // レッド
  '#8b5cf6', // パープル
  '#ec4899', // ピンク
];

export default function ControlPanel({ config, onChangeConfig, onReset }: ControlPanelProps) {
  return (
    <div className="panel-container">
      <div className="panel-title">
        <span>設定コントロール</span>
      </div>

      {/* カラー選択 */}
      <div className="control-group">
        <label className="label">立方体のカラー</label>
        <div className="color-picker-group">
          <input
            type="color"
            value={config.color}
            onChange={(e) => onChangeConfig({ color: e.target.value })}
            style={{
              width: '36px',
              height: '36px',
              padding: 0,
              border: 'none',
              borderRadius: '50%',
              cursor: 'pointer',
              background: 'transparent',
            }}
            title="カスタムカラーピッカー"
          />
          <div className="color-swatches">
            {PRESET_COLORS.map((hex) => {
              const isActive = config.color.toLowerCase() === hex.toLowerCase();
              return (
                <button
                  key={hex}
                  type="button"
                  className={isActive ? 'color-swatch active' : 'color-swatch'}
                  style={{ backgroundColor: hex }}
                  onClick={() => onChangeConfig({ color: hex })}
                  title={hex}
                  aria-label={`色 ${hex} を選択`}
                />
              );
            })}
          </div>
        </div>
      </div>

      {/* トグル設定（自動回転・ワイヤーフレーム） */}
      <div className="control-group">
        <label className="label">表示モード</label>
        <div className="toggle-group">
          <label className="toggle-label">
            <span>自動回転</span>
            <input
              type="checkbox"
              className="checkbox-input"
              checked={config.autoRotate}
              onChange={(e) => onChangeConfig({ autoRotate: e.target.checked })}
            />
          </label>
          <label className="toggle-label">
            <span>ワイヤーフレーム表示</span>
            <input
              type="checkbox"
              className="checkbox-input"
              checked={config.wireframe}
              onChange={(e) => onChangeConfig({ wireframe: e.target.checked })}
            />
          </label>
        </div>
      </div>

      {/* 回転速度スライダー */}
      <div className="control-group">
        <div className="slider-group">
          <div className="slider-label">
            <span>回転速度</span>
            <span>{config.rotationSpeed.toFixed(1)}x</span>
          </div>
          <input
            type="range"
            className="slider-input"
            min="0.2"
            max="3.0"
            step="0.1"
            value={config.rotationSpeed}
            onChange={(e) => onChangeConfig({ rotationSpeed: parseFloat(e.target.value) })}
          />
        </div>
      </div>

      {/* 表面の質感（光沢・粗さ） */}
      <div className="control-group">
        <div className="slider-group">
          <div className="slider-label">
            <span>粗さ (Roughness)</span>
            <span>{Math.round(config.roughness * 100)}%</span>
          </div>
          <input
            type="range"
            className="slider-input"
            min="0.0"
            max="1.0"
            step="0.05"
            value={config.roughness}
            onChange={(e) => onChangeConfig({ roughness: parseFloat(e.target.value) })}
          />
        </div>
      </div>

      {/* 金属感（Metalness） */}
      <div className="control-group">
        <div className="slider-group">
          <div className="slider-label">
            <span>金属感 (Metalness)</span>
            <span>{Math.round(config.metalness * 100)}%</span>
          </div>
          <input
            type="range"
            className="slider-input"
            min="0.0"
            max="1.0"
            step="0.05"
            value={config.metalness}
            onChange={(e) => onChangeConfig({ metalness: parseFloat(e.target.value) })}
          />
        </div>
      </div>

      {/* リセットボタン */}
      <div className="button-group">
        <button
          type="button"
          className="btn btn-reset"
          onClick={() => onReset?.()}
        >
          設定を初期化
        </button>
      </div>
    </div>
  );
}

import { useState } from 'react';
import { CubeConfig } from './types';
import CubeCanvas from './components/CubeCanvas';
import ControlPanel from './components/ControlPanel';

const INITIAL_CONFIG: CubeConfig = {
  color: '#3b82f6',
  wireframe: false,
  autoRotate: true,
  rotationSpeed: 0.8,
  roughness: 0.3,
  metalness: 0.2,
};

export default function App() {
  const [config, setConfig] = useState<CubeConfig>(INITIAL_CONFIG);

  const handleConfigChange = (newValues: Partial<CubeConfig>) => {
    setConfig((prev) => ({ ...prev, ...newValues }));
  };

  const handleReset = () => {
    setConfig({ ...INITIAL_CONFIG });
  };

  return (
    <div className="app-container">
      {/* ヘッダー */}
      <header className="header">
        <h1 className="title">3D インタラクティブ 立方体ビューアー</h1>
        <p className="subtitle">
          Three.jsで描画された立方体を直感的なドラッグ＆スクロールで自在に操作できます
        </p>
      </header>

      {/* メインレイアウト */}
      <main className="main-layout">
        <div className="canvas-wrapper">
          <CubeCanvas config={config} />
        </div>

        <ControlPanel
          config={config}
          onChangeConfig={handleConfigChange}
          onReset={handleReset}
        />
      </main>

      {/* ステータスバー */}
      <footer className="status-bar">
        <div className="status-item">
          <span>カラーコード:</span>
          <strong>{config.color.toUpperCase()}</strong>
        </div>
        <div className="status-item">
          <span>描画モード:</span>
          <strong>{config.wireframe ? 'ワイヤーフレーム' : 'ソリッド (PBR)'}</strong>
        </div>
        <div className="status-item">
          <span>自動回転:</span>
          <strong>{config.autoRotate ? `ON (${config.rotationSpeed.toFixed(1)}x)` : 'OFF'}</strong>
        </div>
        <div className="status-item">
          <span>粗さ / 金属感:</span>
          <strong>{Math.round(config.roughness * 100)}% / {Math.round(config.metalness * 100)}%</strong>
        </div>
      </footer>
    </div>
  );
}
